args.CommandLine:
cat << 'EOF' > patch_sound.rs
use std::fs;

fn main() {
    let mut content = fs::read_to_string("apps/settings/src/main.rs").unwrap();

    // 1. Add Sound to the Route enum
    let route_enum_old = r#"    #[route("/accounts")]
    Accounts,
    #[route("/about")]
    About,"#;
    let route_enum_new = r#"    #[route("/accounts")]
    Accounts,
    #[route("/sound")]
    Sound,
    #[route("/about")]
    About,"#;
    content = content.replace(route_enum_old, route_enum_new);

    // 2. Add Sound to the AppSideBar
    let sidebar_old = r#"            .child(ActivableRoute::new(
                Route::Accounts,
                Link::new(Route::Accounts).child(nav_btn("Accounts", false)),
            ))
            .child(ActivableRoute::new(
                Route::About,"#;
    let sidebar_new = r#"            .child(ActivableRoute::new(
                Route::Accounts,
                Link::new(Route::Accounts).child(nav_btn("Accounts", false)),
            ))
            .child(ActivableRoute::new(
                Route::Sound,
                Link::new(Route::Sound).child(nav_btn("Sound", false)),
            ))
            .child(ActivableRoute::new(
                Route::About,"#;
    content = content.replace(sidebar_old, sidebar_new);

    // 3. Add the Sound Component
    let sound_component = r#"
#[derive(PartialEq)]
struct Sound;
impl Component for Sound {
    fn render(&self) -> impl IntoElement {
        let t = use_app_theme();

        let mut volume = use_state(|| 50.0f64);
        let mut is_muted = use_state(|| false);
        let mut default_sink = use_state(|| "Loading...".to_string());
        let mut loaded = use_state(|| false);

        if !*loaded.read() {
            loaded.set(true);
            let mut vol_state = volume.clone();
            let mut mute_state = is_muted.clone();
            let mut sink_state = default_sink.clone();

            let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();

            std::thread::spawn(move || {
                let mut current_vol = 50.0;
                let mut current_mute = false;
                let mut sink_name = "Unknown Device".to_string();

                // Get Volume
                if let Ok(output) = std::process::Command::new("wpctl").args(&["get-volume", "@DEFAULT_AUDIO_SINK@"]).output() {
                    let out = String::from_utf8_lossy(&output.stdout);
                    // Output format: "Volume: 0.50 [MUTED]"
                    if out.contains("[MUTED]") {
                        current_mute = true;
                    }
                    if let Some(vol_str) = out.split_whitespace().nth(1) {
                        if let Ok(v) = vol_str.parse::<f64>() {
                            current_vol = v * 100.0;
                        }
                    }
                }

                // Get Default Sink Name
                if let Ok(output) = std::process::Command::new("wpctl").args(&["status"]).output() {
                    let out = String::from_utf8_lossy(&output.stdout);
                    // find line with '* ' under Sinks:
                    let mut in_sinks = false;
                    for line in out.lines() {
                        if line.contains("Sinks:") {
                            in_sinks = true;
                            continue;
                        }
                        if in_sinks && line.contains("Sources:") {
                            break;
                        }
                        if in_sinks && line.trim_start().starts_with('*') {
                            // Example: "*   53. Built-in Audio Analog Stereo        [vol: 0.50]"
                            if let Some(name_part) = line.split('.').nth(1) {
                                let name = name_part.split('[').next().unwrap_or_default().trim().to_string();
                                sink_name = name;
                                break;
                            }
                        }
                    }
                }

                let _ = tx.send((current_vol, current_mute, sink_name));
            });

            freya::prelude::spawn(async move {
                if let Some((v, m, s)) = rx.recv().await {
                    vol_state.set(v);
                    mute_state.set(m);
                    sink_state.set(s);
                }
            });
        }

        rect()
            .child(page_header("Sound", "Output and input device management."))
            .child(
                rect()
                    .margin((0., 0., 24., 0.))
                    .padding(24.)
                    .corner_radius(12.)
                    .background(t.bg_card)
                    .border(Border::new().width(1.).fill(t.border_card))
                    .child(label().font_size(14.).font_weight(FontWeight::BOLD).color(t.text_secondary).margin((0., 0., 16., 0.)).text("OUTPUT"))
                    .child(
                        rect()
                            .horizontal()
                            .cross_align(Alignment::Center)
                            .margin((0., 0., 16., 0.))
                            .child(label().font_size(16.).color(t.text_primary).width(Size::fill()).text(default_sink.read().clone()))
                            .child(
                                rect()
                                    .padding(8.)
                                    .corner_radius(8.)
                                    .background(if *is_muted.read() { t.bg_active } else { Color::TRANSPARENT })
                                    .on_press({
                                        let mut m = is_muted.clone();
                                        move |_| {
                                            let new_m = !*m.read();
                                            m.set(new_m);
                                            std::thread::spawn(move || {
                                                let _ = std::process::Command::new("wpctl").args(&["set-mute", "@DEFAULT_AUDIO_SINK@", "toggle"]).output();
                                            });
                                        }
                                    })
                                    .child(label().color(if *is_muted.read() { t.text_primary } else { t.text_muted }).text("Mute"))
                            )
                    )
                    .child(
                        rect()
                            .horizontal()
                            .cross_align(Alignment::Center)
                            .spacing(16.)
                            .child(label().font_size(14.).color(t.text_secondary).text("Volume"))
                            .child(
                                Slider::new({
                                    let mut v = volume.clone();
                                    move |val| {
                                        v.set(val);
                                        let val_clone = val;
                                        std::thread::spawn(move || {
                                            let v_str = format!("{}%", val_clone as i32);
                                            let _ = std::process::Command::new("wpctl").args(&["set-volume", "@DEFAULT_AUDIO_SINK@", &v_str]).output();
                                        });
                                    }
                                }).value(*volume.read())
                            )
                            .child(label().font_size(14.).color(t.text_secondary).width(Size::px(40.)).text(format!("{}%", *volume.read() as i32)))
                    )
            )
    }
}
"#;

    // Append the component above General
    let general_start = "struct General;";
    content = content.replace(general_start, &format!("{}\n{}", sound_component, general_start));

    fs::write("apps/settings/src/main.rs", content).unwrap();
}
